/* Working-memory UI uses the same project ownership, storage and display sync as the desktop. */
(function(){
  'use strict';
  const M=SpatialWorkingMemory, storageKey='spatial-working-memory-v1';
  let model=M.create(readDesktopStorage(storageKey,{version:1,records:{}})), persisted=model.snapshot();
  const area=areaFor('projects');let current='',selected=new Set(),editing=null,draftScope='',lastRemoved=null,temporaryRail=null,previewText='';
  const host=document.createElement('section');host.id='workingMemory';host.className='working-memory';host.setAttribute('aria-label','Working memory');
  host.innerHTML=`<section class="memory-resume"><header><span><svg><use href="#i-monitor"/></svg><b>Continue working</b></span><button class="memory-text-action" data-memory-action="save-place">Save place</button></header><p data-memory-last>No saved place yet. Save your desktop before switching tasks.</p><label class="memory-next-label">Next step<textarea data-memory-next aria-label="Next step" maxlength="500" rows="2" placeholder="Leave yourself a starting point…"></textarea></label><button class="surface-key" data-memory-action="resume" hidden>Return to saved desktop</button></section>
  <section class="memory-shelf"><header><span><svg><use href="#i-note"/></svg><b>Working memory</b></span><small data-memory-count></small></header><p class="memory-scope" data-memory-scope></p><div class="memory-actions"><button class="surface-key" data-memory-action="add">Add note or source</button><button class="memory-text-action" data-memory-action="remember">Keep selection</button></div><p class="memory-help">Drop text or a link here. Select text in an app and press Ctrl+Shift+M to keep its source.</p>
  <form class="memory-editor" hidden><label>Title<input data-memory-title maxlength="120" aria-label="Memory title" placeholder="A useful name"></label><label>Content<textarea data-memory-text maxlength="12000" rows="4" aria-label="Memory content" required placeholder="An excerpt, question or thought…"></textarea></label><label>Source URL or file path<input data-memory-source maxlength="2000" aria-label="Memory source" placeholder="Optional · https://… or /home/…"></label><div class="memory-actions"><button class="surface-key" type="submit">Save to memory</button><button class="memory-text-action" type="button" data-memory-action="cancel">Cancel</button></div></form>
  <div class="memory-selection-tools" hidden><span data-memory-selected></span><div class="memory-actions"><button class="surface-key" data-memory-action="assemble">Assemble note</button><button class="surface-key" data-memory-action="compare">Compare wording</button><button class="memory-text-action" data-memory-action="questions">Find questions &amp; tasks</button><button class="memory-text-action" data-memory-action="clear-selection">Clear selection</button></div><small>Local tools · only the selected items · no AI model connected</small></div>
  <div class="memory-items"></div><section class="memory-preview" hidden aria-label="Memory tool preview"><header><b data-memory-preview-title>Preview</b><button class="memory-text-action" data-memory-action="close-preview">Close</button></header><p data-memory-preview-sources></p><textarea data-memory-preview aria-label="Memory result" rows="7"></textarea><div class="memory-actions"><button class="surface-key" data-memory-action="keep-result">Keep as a note</button></div></section>
  <p class="memory-feedback" role="status"></p><button class="memory-text-action" data-memory-action="undo" hidden>Undo removal</button><details class="memory-history"><summary>Recent activity</summary><ol></ol><button class="memory-text-action" data-memory-action="clear-history">Clear activity</button></details></section>`;
  const rail=document.createElement('button');rail.className='surface-key memory-header-key';rail.dataset.memoryAction='reveal';rail.title='Working memory';rail.setAttribute('aria-label','Open working memory');rail.innerHTML=icon('i-note');$('.area-window-actions',area).prepend(rail);
  const railEntry=document.createElement('button');railEntry.className='surface-key memory-rail-entry rail-action';railEntry.setAttribute('aria-label','Open working memory');railEntry.innerHTML=icon('i-note')+'<span>Memory</span>';area.append(railEntry);
  const searchGroup=document.createElement('section');searchGroup.className='universal-group';searchGroup.dataset.universalGroup='memory';searchGroup.hidden=true;searchGroup.innerHTML='<h3>Working memory · this workspace</h3><div class="universal-result-grid" id="universalMemoryResults"></div>';$('#universalResults').insertBefore(searchGroup,$('[data-universal-group="projects"]'));
  const field=selector=>$(selector,host);
  const scope=()=>M.scope(activeWorkspace,projectColumnActive()?activeProjectName:null);
  const allowed=()=>!globalThis.SpatialGuide?.model.active()||SpatialGuide.model.allows('projects');
  function label(key=current){const [workspace,project]=JSON.parse(key);return project?projectSpaces[project]?.name||'Unavailable project':workspaceProfiles[workspace]?.label+' workspace';}
  function feedback(text){field('.memory-feedback').textContent=text;}
  function save(){try{desktopStorage.setItem(storageKey,JSON.stringify(model.snapshot()));persisted=model.snapshot();queueDesktopStateBroadcast(0);return true;}catch{model=M.create(persisted);feedback('Memory is full in this browser. Remove an item or shorten its content before saving more.');return false;}}
  function sourceFor(id=frontApp){const frame=id&&frameFor(id);if(!frame||!isLocalApp(id))return {label:label(scope()),desktop:desktopPages.current(activeWorkspace)};const address=frame.dataset.fileLocation||$('.browser-toolbar input',frame)?.value||'';return M.source({app:id,label:appInfo[id]?.label+' · '+($('.app-identity small',frame)?.textContent||''),address,desktop:desktopPages.pageOf(activeWorkspace,id)});}
  function selectedText(){const el=document.activeElement;if(el?.matches('textarea,input:not([type="password"])')&&!el.closest('#workingMemory,#universalSearch'))return el.value.slice(el.selectionStart||0,el.selectionEnd||0);const selection=getSelection();if(selection?.anchorNode?.parentElement?.closest('#workingMemory,#universalSearch'))return '';return selection?.toString()||'';}
  let lastSelection=null;
  document.addEventListener('selectionchange',()=>{const text=selectedText().trim();if(text){const parent=getSelection()?.anchorNode?.parentElement;const frame=document.activeElement?.closest('[data-app-frame]')||parent?.closest('[data-app-frame]');lastSelection={text,scope:scope(),source:sourceFor(frame?.dataset.appFrame)};}});
  function remember(){const text=selectedText().trim();const captured=lastSelection?.scope===scope()&&(!text||text===lastSelection.text)?lastSelection:text?{text,scope:scope(),source:sourceFor()}:null;if(!captured?.text||captured.scope!==scope()){reveal();feedback('Select some text in an app first, or use Add note or source.');return;}const item=model.add(captured.scope,{text:captured.text,source:captured.source});if(!item){feedback('This memory holds up to 80 items. Remove an item to make room.');return;}save();render(true);reveal();feedback('Selection saved with its source.');lastSelection=null;}
  function itemMarkup(item){return '<article class="memory-item" data-memory-id="'+escapeHtml(item.id)+'" draggable="true"><header><label class="memory-select"><input type="checkbox" data-memory-select="'+escapeHtml(item.id)+'" aria-label="Select '+escapeHtml(item.title)+'"'+(selected.has(item.id)?' checked':'')+'><b>'+escapeHtml(item.title)+'</b></label><button class="memory-text-action" data-memory-item-action="pin" aria-label="Pin '+escapeHtml(item.title)+'" aria-pressed="'+item.pinned+'">'+(item.pinned?'Pinned':'Pin')+'</button></header><p class="memory-excerpt">'+escapeHtml(item.text)+'</p><small>'+escapeHtml(item.source.label||'Your note')+' · '+escapeHtml(new Date(item.updated).toLocaleDateString(undefined,{month:'short',day:'numeric'}))+'</small>'+(item.source.address?'<span class="memory-source-address">'+escapeHtml(item.source.address)+'</span>':'')+'<div class="memory-item-actions">'+(item.source.address||item.source.app?'<button class="memory-text-action" data-memory-item-action="source">Open source</button>':'')+'<button class="memory-text-action" data-memory-item-action="edit">Edit</button><button class="memory-text-action" data-memory-item-action="remove">Remove</button></div></article>';}
  let signature='';
  function render(force=false){
    const key=scope(),changed=key!==current;host.hidden=!allowed();rail.hidden=!allowed();railEntry.hidden=!allowed();if(!allowed())return;
    if(changed){current=key;selected.clear();editing=null;draftScope='';field('.memory-editor').hidden=true;field('.memory-preview').hidden=true;field('.memory-feedback').textContent='';lastRemoved=null;field('[data-memory-action="undo"]').hidden=true;}
    const target=projectColumnActive()?$('#projectSpaceContent'):$('#projectClosedState');if(host.parentElement!==target){if(projectColumnActive())target.prepend(host);else target.append(host);}
    const items=model.items(key),history=model.history(key),latest=history[0];
    const nextSignature=JSON.stringify([key,items,history,model.nextStep(key),[...selected]]);if(!force&&!changed&&signature===nextSignature)return;signature=nextSignature;
    field('[data-memory-scope]').textContent=label(key)+' · shared across its desktops and displays';field('[data-memory-count]').textContent=items.length+'/80';
    field('[data-memory-last]').textContent=latest?latest.title+' · Desktop '+(latest.desktop+1)+' · '+sessionAge(latest.updated):'No saved place yet. Save your desktop before switching tasks.';
    if(document.activeElement!==field('[data-memory-next]'))field('[data-memory-next]').value=model.nextStep(key);
    field('[data-memory-action="resume"]').hidden=!latest;field('.memory-items').innerHTML=items.length?items.map(itemMarkup).join(''):'<p class="memory-empty">Keep a useful excerpt, reference or question here. It stays after the app closes.</p>';
    selected=new Set([...selected].filter(id=>items.some(item=>item.id===id)));field('.memory-selection-tools').hidden=!selected.size;field('[data-memory-selected]').textContent='Use these '+selected.size+' item'+(selected.size===1?'':'s');field('[data-memory-action="compare"]').disabled=selected.size!==2;
    field('.memory-history ol').innerHTML=history.slice(0,8).map(item=>'<li><button class="memory-text-action" data-memory-visit="'+escapeHtml(item.id)+'">'+escapeHtml(item.title)+'</button><small>Desktop '+(item.desktop+1)+' · '+sessionAge(item.updated)+'</small></li>').join('')||'<li>No activity recorded yet.</li>';
    prepareControlSemantics(host);
  }
  function collapse(){if(!temporaryRail)return;const saved=temporaryRail;temporaryRail=null;if(dockState.projects.edge===saved.edge&&dockSizes[saved.edge]===saved.expanded){dockSizes[saved.edge]=saved.size;dockSizeManual[saved.edge]=saved.manual;layoutDockAreas(false,false);}rail.setAttribute('aria-expanded','false');}
  function reveal(){render();if(!allowed())return;showArea('projects',false);if(area.dataset.areaState==='rail'&&!temporaryRail){const edge=dockState.projects.edge;temporaryRail={edge,size:dockSizes[edge],manual:dockSizeManual[edge],expanded:Math.max(dockSizes[edge],340)};dockSizes[edge]=temporaryRail.expanded;dockSizeManual[edge]=true;layoutDockAreas(false,false);}rail.setAttribute('aria-expanded','true');requestAnimationFrame(()=>host.scrollIntoView({block:'start',behavior:'smooth'}));}
  function editor(item=null){reveal();editing=item?.id||null;draftScope=current;field('.memory-editor').hidden=false;field('[data-memory-title]').value=item?.title||'';field('[data-memory-text]').value=item?.text||'';field('[data-memory-source]').value=item?.source.address||'';field('[data-memory-title]').focus();}
  function record(id=frontApp,explicit=false){if(!allowed()||globalThis.SpatialGuide?.settingUp||desktopSyncApplying)return;const key=scope();if(!explicit&&(!id||appState[id]!=='open'||!isLocalApp(id)))return;const source=sourceFor(id);model.visit(key,{title:explicit?'Saved working place':source.label,desktop:desktopPages.current(activeWorkspace),source,apps:Object.keys(appState).filter(name=>appState[name]==='open'&&isLocalApp(name))});save();render();}
  function resume(item){if(!item)return;const [workspace,project]=JSON.parse(item.scope);if(workspace!==activeWorkspace||project&&!projectSpaces[project]){feedback('This source is no longer available in this workspace.');return;}
    const column=project||'workspace';if(project&&!openProjectNames().includes(project))activateProject(project,false);changeDesktopPage(item.desktop,false,column);
    item.apps.forEach(id=>{if(appInfo[id]&&desktopPages.columnOf(activeWorkspace,id)===column&&desktopPages.pageOf(activeWorkspace,id)===item.desktop)openApp(id);});focusDesktop(false);reveal();feedback('Returned to Desktop '+(item.desktop+1)+'. Current document contents were kept.');}
  function openSource(item){const src=item.source;if(src.address){if(/^https?:\/\//i.test(src.address)){const id=createAppInstance('browser');navigateBrowser(id,src.address);}else{const id=createAppInstance('dolphin');const file=/\.[a-z0-9]{1,10}$/i.test(src.address);renderFileLocation(id,file?src.address.slice(0,src.address.lastIndexOf('/'))||'/':src.address);if(file)openAppFile(id,src.address.split('/').at(-1));}return;}if(src.app&&appInfo[src.app]){const owner=desktopPages.columnOf(activeWorkspace,src.app);if(owner!==(JSON.parse(item.scope)[1]||'workspace')){feedback('The source window has moved to another project. Its saved excerpt is still here.');return;}changeDesktopPage(desktopPages.pageOf(activeWorkspace,src.app),false,owner);openApp(src.app);}else feedback('The original app is unavailable. The saved excerpt remains in memory.');}
  function preview(action){const items=model.items(current).filter(item=>selected.has(item.id));if(!items.length)return;let title='Assembled note',text=M.compose(items);
    if(action==='compare'){const result=M.compare(items);if(!result)return;title='Wording comparison';const section=(name,lines)=>name+'\n'+(lines.length?lines.map(line=>'• '+line).join('\n'):'No matching lines.');text=[section('Shared lines',result.shared),section('Only in '+items[0].title,result.onlyFirst),section('Only in '+items[1].title,result.onlySecond)].join('\n\n');}
    if(action==='questions'){title='Questions & tasks';const found=items.flatMap(item=>item.text.split(/\n|(?<=[.!?])\s+/).filter(line=>/\?|\b(todo|next|check|review|test|fix|verify|remember)\b/i.test(line)).map(line=>'• '+line.trim()+' ['+item.title+']'));text=found.length?found.join('\n'):'No explicit questions or task phrases were found. Add your own next step below.';}
    previewText=title;field('[data-memory-preview-title]').textContent=title;field('[data-memory-preview-sources]').textContent='Local tool using: '+items.map(item=>item.title).join(', ')+'. Review and edit before keeping.';field('[data-memory-preview]').value=text;field('.memory-preview').hidden=false;field('.memory-preview').scrollIntoView({block:'nearest'});
  }
  host.addEventListener('submit',event=>{event.preventDefault();if(draftScope!==scope())return;const address=field('[data-memory-source]').value.trim();if(address&&!/^(https?:\/\/|\/)/i.test(address)){feedback('Use an HTTP(S) address or an absolute file path for the source.');return;}const value={title:field('[data-memory-title]').value,text:field('[data-memory-text]').value,source:{...(editing?model.get(editing)?.source:{}),label:editing?model.get(editing)?.source.label:'Your note',address}};const item=editing?model.edit(editing,value):model.add(current,value);if(!item){feedback('Memory is full or the content is empty.');return;}if(save()){field('.memory-editor').hidden=true;editing=null;render(true);feedback('Saved to '+label()+'.');}});
  host.addEventListener('change',event=>{const id=event.target.dataset.memorySelect;if(id){event.target.checked?selected.add(id):selected.delete(id);render(true);}});
  host.addEventListener('input',event=>{if(event.target.matches('[data-memory-next]')){model.next(current,event.target.value);save();}});
  host.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;const id=button.closest('[data-memory-id]')?.dataset.memoryId,item=id&&model.get(id),action=button.dataset.memoryAction||button.dataset.memoryItemAction;
    if(button.dataset.memoryVisit){resume(model.get(button.dataset.memoryVisit));return;}
    if(action==='add')editor();if(action==='cancel')field('.memory-editor').hidden=true;if(action==='remember')remember();if(action==='save-place')record(frontApp,true);if(action==='resume')resume(model.history(current)[0]);
    if(action==='edit')editor(item);if(action==='source')openSource(item);if(action==='pin'){model.edit(id,{pinned:!item.pinned});save();render(true);}if(action==='remove'){model.remove(id);lastRemoved=id;save();render(true);field('[data-memory-action="undo"]').hidden=false;feedback('Removed '+item.title+'.');}if(action==='undo'&&lastRemoved){model.restore(lastRemoved);save();render(true);lastRemoved=null;button.hidden=true;feedback('Item restored.');}
    if(['assemble','compare','questions'].includes(action))preview(action);if(action==='close-preview')field('.memory-preview').hidden=true;if(action==='clear-selection'){selected.clear();render(true);}if(action==='keep-result'){const text=field('[data-memory-preview]').value;const result=model.add(current,{title:previewText,text,source:{label:'Local tool · '+selected.size+' selected sources'}});if(result&&save()){field('.memory-preview').hidden=true;render(true);feedback('Result kept as an editable note.');}}
    if(action==='clear-history'){model.history(current).forEach(item=>model.remove(item.id));save();render(true);feedback('Recent activity cleared. Your saved notes remain.');}
  });
  host.addEventListener('dragstart',event=>{if(event.target.closest('input,textarea,button'))return;const item=model.get(event.target.closest('[data-memory-id]')?.dataset.memoryId);if(!item)return;event.dataTransfer.setData('text/plain',item.text);if(/^https?:\/\//.test(item.source.address))event.dataTransfer.setData('text/uri-list',item.source.address);event.dataTransfer.effectAllowed='copy';});
  host.addEventListener('dragover',event=>{if(event.dataTransfer.types.some(type=>['text/plain','text/uri-list'].includes(type))){event.preventDefault();event.dataTransfer.dropEffect='copy';host.classList.add('is-drop-target');}});
  host.addEventListener('dragleave',event=>{if(!host.contains(event.relatedTarget))host.classList.remove('is-drop-target');});
  host.addEventListener('drop',event=>{host.classList.remove('is-drop-target');if(event.target.closest('textarea,input'))return;const text=event.dataTransfer.getData('text/plain'),url=event.dataTransfer.getData('text/uri-list').split('\n').find(line=>!line.startsWith('#'));if(!text&&!url)return;event.preventDefault();event.stopPropagation();const item=model.add(current,{text:text||url,source:{label:'Dropped content',address:url||''}});if(item){save();render(true);feedback('Dropped content saved.');}});
  [rail,railEntry].forEach(button=>button.addEventListener('click',()=>{reveal();field('[data-memory-action="add"]').focus();}));
  document.addEventListener('pointerdown',event=>{if(temporaryRail&&!area.contains(event.target))collapse();},true);
  document.addEventListener('focusin',event=>{if(temporaryRail&&!area.contains(event.target))collapse();});
  document.addEventListener('keydown',event=>{if(event.ctrlKey&&event.shiftKey&&event.code==='KeyM'&&allowed()){event.preventDefault();remember();}if(event.key==='Escape'&&temporaryRail)collapse();});
  document.addEventListener('click',event=>{const frame=event.target.closest('[data-app-frame]');if(frame)setTimeout(()=>record(frame.dataset.appFrame),0);});
  document.addEventListener('click',event=>{const result=event.target.closest('[data-memory-result]');if(!result)return;const item=model.get(result.dataset.memoryResult);if(!item)return;const [,project]=JSON.parse(item.scope);setUniversalSearchOpen(false);if(project&&projectSpaces[project])activateProject(project,false);else changeDesktopPage(desktopPages.current(activeWorkspace),false,'workspace');render(true);reveal();const row=$('[data-memory-id="'+CSS.escape(item.id)+'"]',host);row?.scrollIntoView({block:'center'});if(item.kind==='next')field('[data-memory-next]').focus();else row?.querySelector('input')?.focus();});
  function search(query){const results=allowed()?model.search(query,activeWorkspace).filter(item=>!JSON.parse(item.scope)[1]||projectSpaces[JSON.parse(item.scope)[1]]):[];$('#universalMemoryResults').innerHTML=results.map(item=>'<button class="universal-result" data-memory-result="'+escapeHtml(item.id)+'"><span class="universal-symbol">'+icon('i-note')+'</span><span><b>'+escapeHtml(item.title)+'</b><small>'+escapeHtml(label(item.scope)+' · '+(item.source.label||'Your note')+' · '+sessionAge(item.updated))+'</small><small>'+escapeHtml(item.text.slice(0,120))+'</small></span></button>').join('');prepareControlSemantics(searchGroup);return results.length;}
  function seed(){if(desktopPreset!=='demo'||globalThis.SpatialGuide?.model.active())return;Object.entries(projectSpaces).forEach(([id,project])=>{if(!SpatialDemoExamples.projects[id]||project.name!==SpatialDemoExamples.projects[id].name)return;const workspace=project.originWorkspace;if(!workspaceProfiles[workspace])return;const key=M.scope(workspace,id);if(model.seeded(key))return;model.markSeeded(key);if(project.note)model.add(key,{title:'Project starting point',text:project.note,source:{label:project.name+' · Quick note',address:project.root}});model.add(key,{title:'Questions for the next review',text:'What is ready to share?\nWhat still needs testing?\nNext: review the project starting point before opening another task.',source:{label:'Demo planning note'}});model.next(key,project.note||'Review the project references.');});save();}
  globalThis.SpatialMemoryDesktop={render,search,remember,record,snapshot:()=>model.snapshot(),merge(value){if(model.merge(value)){try{desktopStorage.setItem(storageKey,JSON.stringify(model.snapshot()));persisted=model.snapshot();}catch{}render(true);}}};
  seed();render(true);prepareControlSemantics(rail.parentElement);
})();
